package ua.deutschpro.player;
import android.app.*; import android.content.*; import android.os.*; import android.media.*; import android.media.session.*; import android.speech.tts.*; import java.util.*;
public class PlayerService extends Service {
 public static volatile boolean playing=false; public static volatile String status="Готово до відтворення"; public static volatile int stage=0;
 Handler h=new Handler(Looper.getMainLooper()); TextToSpeech tts; boolean ready=false,want=false,foreground=false; int generation=0; MediaSession session; PowerManager.WakeLock wake;
 public static void command(Context c,String a){Intent i=new Intent(c,PlayerService.class).setAction(a);if(a.equals("PLAY")||a.equals("TOGGLE")){if(Build.VERSION.SDK_INT>=26)c.startForegroundService(i);else c.startService(i);}else c.startService(i);}
 public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26){NotificationChannel ch=new NotificationChannel("player","Аудіоуроки",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(ch);} session=new MediaSession(this,"Language Pro");session.setCallback(new MediaSession.Callback(){public void onPlay(){play();}public void onPause(){pause();}public void onSkipToNext(){move(1);}public void onSkipToPrevious(){move(-1);}public void onStop(){pause();stopSelf();}});session.setActive(true);wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"DeutschPro:player");tts=new TextToSpeech(this,s->{h.post(()->{ready=s==TextToSpeech.SUCCESS;if(ready&&want)speak();else if(!ready){status="Не вдалося запустити синтез голосу";pause();}});});tts.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String s){}public void onDone(String s){h.post(()->done(s));}public void onError(String s){h.post(()->{if(s.equals(id())){pause();status="Помилка голосу. Перевір мовні пакети Android.";}});}});}
 int l(){return Store.prefs(this).getInt("lesson",0);}int p(){return Store.prefs(this).getInt("phrase",0);}String id(){return "u"+generation+"_"+stage;}
 public int onStartCommand(Intent i,int flags,int startId){String a=i==null?"STOP":i.getAction();if(a==null)a="STOP";switch(a){case "PLAY":play();break;case "TOGGLE":if(playing)pause();else play();break;case "PAUSE":pause();break;case "NEXT":move(1);break;case "PREV":move(-1);break;case "RESET":cancel();stage=0;if(playing)speak();refresh();break;case "STOP":pause();stopSelf();break;}return START_NOT_STICKY;}
 void play(){if(playing){refresh();return;}if(Store.phrases(this,l()).length()==0){status="Спочатку додай урок";stopSelf();return;}want=true;playing=true;generation++;stage=0;if(!wake.isHeld())wake.acquire();refresh();if(ready)speak();else status="Завантаження голосів…";}
 void cancel(){generation++;if(tts!=null)tts.stop();}
 void pause(){want=false;playing=false;cancel();if(wake!=null&&wake.isHeld())wake.release();status="На паузі";refresh();if(foreground){stopForeground(false);foreground=false;}}
 void move(int delta){cancel();int a=l(),b=p()+delta,n=Store.phrases(this,a).length();if(n==0)return;if(b<0){if(Store.adjacent(this,a,-1)>=0){a=Store.adjacent(this,a,-1);b=Store.phrases(this,a).length()-1;}else b=0;}else if(b>=n){if(Store.adjacent(this,a,1)>=0){a=Store.adjacent(this,a,1);b=0;}else b=n-1;}Store.prefs(this).edit().putInt("lesson",a).putInt("phrase",b).apply();stage=0;if(playing&&ready)speak();refresh();}
 void speak(){if(!playing||!ready)return;String lang=stage==1?"uk":"de";String phrase=Store.phrase(this,l(),p(),lang);if(phrase.isEmpty()){pause();return;}int r=tts.setLanguage(stage==1?Locale.forLanguageTag("uk-UA"):Store.locale(Store.language(this,l())));if(r==TextToSpeech.LANG_MISSING_DATA||r==TextToSpeech.LANG_NOT_SUPPORTED){pause();status="Встанови голос "+(stage==1?"української":Store.name(Store.language(this,l())))+" мови в Android";return;}tts.setSpeechRate(Store.prefs(this).getFloat("speed",0.85f));status=stage==1?"Український переклад":stage==2?"Повторення • "+Store.name(Store.language(this,l())):Store.name(Store.language(this,l()));tts.speak(phrase,TextToSpeech.QUEUE_FLUSH,null,id());refresh();}
 void done(String s){if(!playing||!s.equals(id()))return;int g=generation;status="Пауза для повторення";int delay=Store.prefs(this).getInt("pause",4)*1000;h.postDelayed(()->{if(!playing||g!=generation)return;if(stage==0&&Store.phrase(this,l(),p(),"uk").trim().isEmpty()){stage=2;speak();}else if(stage<2){stage++;speak();}else{int a=l(),b=p();boolean repeat=Store.prefs(this).getBoolean("repeat",false),auto=Store.prefs(this).getBoolean("auto",true);if(b+1<Store.phrases(this,a).length())b++;else if(repeat)b=0;else if(auto&&Store.adjacent(this,a,1)>=0){a=Store.adjacent(this,a,1);b=0;}else{pause();status="Урок завершено";return;}Store.prefs(this).edit().putInt("lesson",a).putInt("phrase",b).apply();stage=0;generation++;speak();}},delay);}
 PendingIntent action(String a,int req){return PendingIntent.getService(this,req,new Intent(this,PlayerService.class).setAction(a),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
 void refresh(){if(session==null)return;session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,Store.phrase(this,l(),p(),"de")).putString(MediaMetadata.METADATA_KEY_ARTIST,Store.title(this,l())).build());session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_STOP).setState(playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,0,playing?1:0).build());Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"player"):new Notification.Builder(this);Notification n=b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(Store.phrase(this,l(),p(),"de")).setContentText(Store.title(this,l())).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).setVisibility(Notification.VISIBILITY_PUBLIC).setOngoing(playing).addAction(android.R.drawable.ic_media_previous,"Назад",action("PREV",1)).addAction(playing?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,playing?"Пауза":"Грати",action("TOGGLE",2)).addAction(android.R.drawable.ic_media_next,"Далі",action("NEXT",3)).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2)).build();if(playing){startForeground(20,n);foreground=true;}else if(foreground)getSystemService(NotificationManager.class).notify(20,n);}
 public IBinder onBind(Intent i){return null;}public void onDestroy(){cancel();playing=false;want=false;if(tts!=null)tts.shutdown();if(session!=null)session.release();if(wake!=null&&wake.isHeld())wake.release();super.onDestroy();}
}
